import React, { useEffect, useState } from 'react';

import {
  getEquipos,
  createEquipo
} from '../services/api';

import StatusBadge from '../components/StatusBadge';

import {
  LoadingSpinner,
  ErrorState,
  EmptyState
} from '../components/StateHelpers';

const ROLES = [
  'Developer',
  'Designer',
  'Manager',
  'DevOps',
  'QA',
  'Consultor'
];

export default function Equipos() {

  const [equipos, setEquipos] = useState([]);

  const [loading, setLoading] = useState(true);

  const [error, setError] = useState(null);

  // ============================================
  // FORMULARIO
  // ============================================

  const [nuevoEquipo, setNuevoEquipo] = useState({
    nombreEquipo: '',
    rol: 'Developer',
    estado: 'Activo',
  });

  // ============================================
  // CARGAR EQUIPOS
  // ============================================

  const cargarEquipos = async () => {

    try {

      setLoading(true);

      const data = await getEquipos();

      setEquipos(Array.isArray(data) ? data : []);

      setError(null);

    } catch (e) {

      setError(e.message);

    } finally {

      setLoading(false);

    }
  };

  useEffect(() => {
    cargarEquipos();
  }, []);

  // ============================================
  // CREAR EQUIPO
  // ============================================

  const handleSubmit = async (e) => {

    e.preventDefault();

    try {

      await createEquipo(nuevoEquipo);

      setNuevoEquipo({
        nombreEquipo: '',
        rol: 'Developer',
        estado: 'Activo',
      });

      cargarEquipos();

    } catch (e) {

      console.error(e);

      alert('Error al crear equipo');
    }
  };

  // ============================================
  // AGRUPAR POR ROL
  // ============================================

  const gruposPorRol = ROLES.map((rol) => ({
    rol,
    miembros: equipos.filter((e) => e.rol === rol),
  })).filter((g) => g.miembros.length > 0);

  // ============================================
  // ESTADOS
  // ============================================

  if (loading) return <LoadingSpinner />;

  if (error) {
    return (
      <ErrorState
        message={`Error al cargar equipos. ${error}`}
      />
    );
  }

  // ============================================
  // RENDER
  // ============================================

  return (
    <div className="section-fade">

      {/* TITULO */}

      <div className="section-title">
        Equipos
      </div>

      <div className="section-sub">
        Gestión de equipos y recursos
      </div>

      {/* ========================================= */}
      {/* FORMULARIO */}
      {/* ========================================= */}

      <div className="data-card mb-4">

        <div className="data-card-header">
          <h5>
            <i
              className="bi bi-plus-circle me-2"
              style={{ color: 'var(--accent)' }}
            ></i>

            Crear Equipo
          </h5>
        </div>

        <div style={{ padding: '20px' }}>

          <form onSubmit={handleSubmit}>

            <div className="row g-3">

              {/* NOMBRE */}

              <div className="col-md-4">

                <label className="form-label">
                  Nombre Equipo
                </label>

                <input
                  type="text"
                  className="form-control"
                  required
                  value={nuevoEquipo.nombreEquipo}
                  onChange={(e) =>
                    setNuevoEquipo({
                      ...nuevoEquipo,
                      nombreEquipo: e.target.value,
                    })
                  }
                />

              </div>

              {/* ROL */}

              <div className="col-md-4">

                <label className="form-label">
                  Rol
                </label>

                <select
                  className="form-select"
                  value={nuevoEquipo.rol}
                  onChange={(e) =>
                    setNuevoEquipo({
                      ...nuevoEquipo,
                      rol: e.target.value,
                    })
                  }
                >

                  {ROLES.map((rol) => (

                    <option key={rol} value={rol}>
                      {rol}
                    </option>

                  ))}

                </select>

              </div>

              {/* ESTADO */}

              <div className="col-md-4">

                <label className="form-label">
                  Estado
                </label>

                <select
                  className="form-select"
                  value={nuevoEquipo.estado}
                  onChange={(e) =>
                    setNuevoEquipo({
                      ...nuevoEquipo,
                      estado: e.target.value,
                    })
                  }
                >

                  <option value="Activo">
                    Activo
                  </option>

                  <option value="Inactivo">
                    Inactivo
                  </option>

                </select>

              </div>

              {/* BOTON */}

              <div className="col-12">

                <button
                  type="submit"
                  className="btn btn-primary"
                >
                  <i className="bi bi-save me-2"></i>

                  Crear Equipo
                </button>

              </div>

            </div>

          </form>

        </div>

      </div>

      {/* ========================================= */}
      {/* LISTADO */}
      {/* ========================================= */}

      <div className="data-card">

        <div className="data-card-header">

          <h5>

            <i
              className="bi bi-diagram-3 me-2"
              style={{ color: 'var(--accent2)' }}
            ></i>

            Vista de Equipos

          </h5>

        </div>

        {gruposPorRol.length ? (

          <div style={{ padding: '16px' }}>

            <div className="row g-3">

              {gruposPorRol.map(({ rol, miembros }) => (

                <div className="col-md-4" key={rol}>

                  <div
                    style={{
                      background: 'var(--surface2)',
                      border: '1px solid var(--border)',
                      borderRadius: '12px',
                      padding: '18px',
                    }}
                  >

                    {/* TITULO */}

                    <div
                      style={{
                        fontFamily: "'Syne', sans-serif",
                        fontWeight: 700,
                        marginBottom: '12px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                      }}
                    >

                      {rol}

                      <span
                        style={{
                          fontSize: '11px',
                          background: 'rgba(79,140,255,0.1)',
                          color: 'var(--accent)',
                          padding: '2px 8px',
                          borderRadius: '10px',
                        }}
                      >
                        {miembros.length}
                      </span>

                    </div>

                    {/* MIEMBROS */}

                    {miembros.map((equipo) => (

                      <div
                        key={equipo.id}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '8px',
                          padding: '7px 0',
                          borderBottom: '1px solid var(--border)',
                        }}
                      >

                        {/* AVATAR */}

                        <div
                          className="avatar"
                          style={{
                            width: '26px',
                            height: '26px',
                            fontSize: '10px'
                          }}
                        >
                          {(equipo.nombreEquipo || '?')
                            .charAt(0)}
                        </div>

                        {/* NOMBRE */}

                        <span style={{ fontSize: '13px' }}>
                          {equipo.nombreEquipo}
                        </span>

                        {/* ESTADO */}

                        <div style={{ marginLeft: 'auto' }}>

                          <StatusBadge
                            estado={equipo.estado}
                          />

                        </div>

                      </div>

                    ))}

                  </div>

                </div>

              ))}

            </div>

          </div>

        ) : (

          <EmptyState
            message="No existen equipos registrados."
          />

        )}

      </div>

    </div>
  );
}
